    rows.append(dict(id=f'{76+len(rows):03}',title=title,category=category,original_error_text=None,error_code=code,error_codes=codes,rule_codes=rules,status_codes=list(status_codes),error_namespace='Проверка СЭМД в 1C-MR' if rules or status_codes else 'РЭМД',alternative_search_phrases=list(dict.fromkeys([*codes,*rules,*markers,title])),keywords=re.findall(r'[\w-]+',title.lower()),workflow=workflow,cause=cause,cause_confidence='Возможная причина' if possible else 'Расшифровка или условие подтверждены источником',physician_instructions=steps,escalation_instructions='Местная поддержка МИС: передайте код, уточняющие слова сообщения, вид документа, время сбоя и его текущий статус без данных пациента.',source_urls=urls,evidence_status=['Возможно' if possible else 'Подтверждено','Требует локальной проверки'],software_product=product,software_version=version,local_verification_status='В целевой больнице Иванова не проверено',source_date=date,checked_on='2026-10-30',evidence_note=note or 'Источник описывает этот случай. Безопасные шаги для врача — редакционная адаптация; успешное устранение в целевой больнице не проверено.',source_locator=('Правила '+', '.join(rules) if rules else 'Разбор '+str(code or ', '.join(status_codes))),confirmed_solution=solved,clarifying_questions=['Какой вид документа и какая система указаны на рабочем месте?','Какие слова идут после кода? Передайте только обезличенный фрагмент.','Каков текущий статус документа?'],safety_note='Сначала проверьте состояние исходного документа. Исправление подписанного документа и повторную отправку согласуйте по местному порядку; не удаляйте запись или подписи.',diagnostic_markers=list(markers),context_required=bool(rules or code in ('500','VALIDATION_ERROR','XML_VALIDATION_ERROR'))))

