add('Одна подпись передана дважды','SIGNATURE_DUPLICATION','В отправленном документе повторяется подпись одного сотрудника.', ['Проверьте список подписантов и статус исходного документа; не подписывайте его ещё раз.','Попросите поддержку согласовать исправление повторной подписи. Самостоятельно удалять подписи или менять готовность документа не нужно.'],'65110619',date='2023-05-23',category='Подписание документов',markers=['дублирование подписи','DOCTOR'],note='В исходной статье предлагается сброс подписей сменой статуса. Эта операция не перенесена в действия врача.')
add('Подпись не прошла проверку','SIGNATURE_VERIFICATION_ERROR','Возможная причина: сертификат, которым подписано направление, отозван. Код сам по себе этого не доказывает.', ['Сверьте выбранного подписанта и дату документа. Не заменяйте дату ради прохождения проверки.','Передайте поддержке проверку подписи и сертификата. Новый сертификат и повторное подписание применяются только после согласования исправления исходной записи.'],'76972049',date='2023-07-10',possible=True,category='Подписание документов',markers=['Signature is invalid','ЭП сотрудника не верна'],workflow='Регистрация подписанного направления на МСЭ')
add('РЭМД не смог прочитать подпись','SIGNATURE_DECODING_ERROR','Возможная причина: сбой проверки подписи или проблема сертификата; статья перечисляет несколько вариантов.', ['Запишите код и дополнительные слова сообщения, проверьте статус документа.','Попросите поддержку выяснить, требуется ли проверка сертификата или ожидание восстановления сервиса. Не перевыпускайте сертификат только по этому коду.'],'118980806',date='2024-10-07',possible=True,category='Подписание документов')
add('Не подтверждена цепочка доверия сертификата','CANT_BUILD_CERT_CHAIN_TO_ACCREDITED_CA_CERT','Проверка не смогла подтвердить доверие к сертификату подписанта.', ['Уточните, о подписи врача или организации говорится в сообщении.','Передайте поддержке проверку действительности сертификатов всех подписантов и цепочки доверия. Не устанавливайте сертификаты и не отключайте проверку самостоятельно.'],'24293154',date='2023-05-23',category='Подписание документов',markers=['цепочку сертификатов','Головного УЦ'])
add('Удостоверяющий центр недоступен','CA_INACCESSIBILITY','Сервис проверки сертификата недоступен; это не доказывает истечение срока вашей подписи.', ['Проверьте, остался ли документ в очереди или получил окончательный отказ.','Уточните у поддержки, выполняется ли автоматическая повторная отправка. При срочной работе используйте местный порядок действий при сбое.'],'65110653',date='2023-05-30',category='Подписание документов',markers=['центр сертификата недоступен'])
add('Данные врача не совпали с сертификатом','VALUE_MISMATCH_METADATA_AND_CERTIFICATE','Сведения о подписанте в документе отличаются от сведений в сертификате.', ['Сверьте автора и выбранную собственную подпись; уточните название несовпавшего поля из сообщения.','Передайте поддержке сверку данных сотрудника и сертификата. Не выбирайте чужую подпись и не исправляйте персональные данные наугад.'],'65110627',date='2023-05-23',category='Подписание документов',markers=['GIVEN_NAME','данных подписанта','SNILS в метаданных'])
add('Сведения о враче отличаются от ФРМР','VALUE_MISMATCH_METADATA_AND_FRMR','Данные сотрудника в медицинской системе и федеральном регистре различаются.', ['Посмотрите, какое поле указано в сообщении: например, дата рождения или имя.','Обратитесь к ответственному за ФРМР и поддержке для сверки с действительными документами. После исправления согласуйте дальнейшие действия с исходной записью.'],'65110623',date='2023-05-23',markers=['данные сотрудника не соответствуют данным ФРМР'])
add('Не передано подразделение врача','NO_DEPARTMENT','В сведениях для регистрации отсутствует подразделение организации; поддержка рекомендует проверить его идентификатор.', ['Проверьте, в каком отделении и от какого сотрудника оформлен документ.','Попросите поддержку проверить привязку сотрудника к подразделению и его идентификатор. Настройки подразделений самостоятельно не изменяйте.'],'65110642',date='2023-05-24',markers=['Отсутствует информация о подразделении'])
add('Для документа не передан СНИЛС пациента','NO_SNILS','Проверка требует СНИЛС для данного вида документа, но не получила его.', ['На рабочем месте проверьте данные пациента и тип документа. Не используйте СНИЛС родителя вместо СНИЛС ребёнка.','Если СНИЛС действительно отсутствует, уточните у регистратора и поддержки допустимый порядок для этого вида документа и пациента. Если данные есть, поддержка проверяет их передачу.'],'65110625',date='2023-05-23',markers=['СНИЛС пациента обязателен'],note='Заполнение известного реквизита описано источником; исключения для отдельных пациентов и видов СЭМД здесь не устанавливаются.')
add('Данные пациента расходятся с федеральной записью','PATIENT_MPI_MISMATCH','Сведения в отправленном документе отличаются от федеральной записи. В описанном случае нужно учитывать данные на дату создания СЭМД.', ['Сверьте личность на рабочем месте и название несовпавшего поля. Уточните, менялись ли данные после создания документа.','Передайте разбор регистратору и поддержке. Не создавайте новую карту и не объединяйте пациентов для обхода ошибки.'],'65110598',date='2023-05-23',markers=['не соответствует данным ГИП','Пациент найден по локальному идентификатору'])
add('Документ уже зарегистрирован, но в МИС остаётся ошибка','NOT_UNIQUE_PROVIDED_ID','РЭМД уже знает этот идентификатор документа; локальный статус может не отражать регистрацию.', ['Не создавайте копию и не отправляйте документ заново. Проверьте его текущий статус.','Попросите администратора сверить регистрацию и обновить статус по результату поиска в РЭМД. В статье описано исправление для регионального релиза 33.'],'65110617',date='2023-05-23',version='Релиз 33 в региональной линии 1C-MR',solved=True,markers=['документ с идентификатором уже зарегистрирован'])
add('Новая версия направления на МСЭ запрещена','RESTRICT_NEW_VERSION','Для описанного вида направления зарегистрированный документ нельзя заменить новой версией.', ['Проверьте, зарегистрировано ли исходное направление и какие сведения нужно исправить.','Согласуйте с ответственным за МСЭ и поддержкой порядок исправления. Не создавайте повторное направление до проверки исходной регистрации.'],'80085223',date='2023-09-04',version='Направление на МСЭ, вид 109, редакция 5; релиз МИС неизвестен',workflow='Исправление зарегистрированного направления на МСЭ',note='Статья 2023 года описывает новый документ при необходимости коррекции. Более поздняя статья об автоматической обработке имеет другой технический контекст; универсальный порядок не заявляется.')
add('Внутренняя ошибка РЭМД','RUNTIME_ERROR','Возможная причина: временный сбой обработки в РЭМД. Дополнительные сведения могут уточнить причину.', ['Запишите время, вид документа и полный код без данных пациента.','Уточните у поддержки состояние очереди и автоматическую обработку. Не повторяйте отправку вручную, пока не проверен результат предыдущей.'],'24293138',date='2023-05-23',possible=True,markers=['Internal error','Непредвиденная ошибка'],note='Автоматическая обработка описана для определённой региональной реализации; её наличие в больнице неизвестно.')
add('500: превышен лимит запросов к сервису','500','Этот вариант 500 сопровождается сообщением о превышении лимита запросов. По одному числу 500 причину определить нельзя.', ['Сверьте слова «превышен лимит запросов» в сообщении. Если их нет, выберите другой случай.','Не нажимайте отправку многократно. Передайте поддержке проверку очереди и предусмотренной автоматической повторной обработки.'],'46009238',date='2023-05-23',markers=['превышен лимит запросов','Доступ к сервису временно запрещён'])
add('500: вместо ответа получено неверное SOAP-сообщение','500','В описанном случае ответ внешнего сервиса не удалось прочитать. Это другой вариант 500, а не ошибка заполнения эпикриза.', ['Сверьте фрагменты «SOAP», «unmarshalling» или «end-tag» после кода.','Проверьте статус документа и сообщите поддержке время сбоя. Автоматическую обработку и доступность обмена проверяет администратор.'],'24293135',date='2023-05-23',markers=['SOAP','unmarshalling','end-tag','element type hr'],note='Статья связывает конкретный ответ с нестабильностью РЭМД; расписание повторной отправки зависит от реализации.')
add('В направлении на МСЭ пустой телефон','XML_VALIDATION_ERROR','В этом случае ошибка содержит «tel:» и «anyURI»: в направлении отсутствует номер телефона.', ['Сверьте эти слова: один код XML_VALIDATION_ERROR не указывает на телефон.','Если имеется действительный номер, проверьте его перенос в направление. Исправление уже подписанного направления и повторное формирование согласуйте с ответственным за МСЭ.'],'83787833',date='2023-10-19',workflow='Проверка направления на МСЭ',markers=['tel:','anyURI','cvc-datatype-valid.1.2.1'],solved=True,status_codes=['301'],note='Источник описывает заполнение телефона. Статус 301 с тем же текстом подтверждён отдельной статьёй 159252710; это статус проверки СЭМД, не HTTP.')
