rule('У1-20: не передан вид полиса в направлении на МСЭ','У1-20',['InsurancePolicy','InsurancePolicyType'],'Возможная причина: в данных пациента выбран вариант отсутствия полиса; проверка не получает нужный вид полиса.', ['Сверьте действительный полис и наличие фрагмента InsurancePolicyType.','Передайте регистратору проверку типа полиса. При реальном отсутствии полиса запросите допустимый порядок, не подставляя чужие сведения.'],'76972065',date='2024-02-16',possible=True)
rule('У1-20: не указан вид документа представителя','У1-20',['guardian','AuthorityDoc','IdentityCardType'],'В описанном случае не заполнен вид документа законного представителя.', ['Проверьте, что ошибка относится к представителю: в тексте есть guardian или AuthorityDoc.','Уточните документ представителя у ответственного за регистрацию и исправьте только подтверждённые сведения. Не подменяйте ими документ самого пациента.'],'76972065',date='2024-02-16',solved=True)
rule('У1-21: в направлении не определён автор','У1-21',['count(author)','author'],'Не переданы сведения об авторе; источник связывает это с ответственным сотрудником и его учётной записью.', ['Проверьте автора направления и собственную учётную запись.','Если автор указан верно, попросите поддержку проверить связи сотрудника с учётной записью. Не входите под чужим именем и не меняйте автора формально.'],'74317888',date='2023-10-18')
rule('У1-21: должность автора выгружается пустой','У1-21',['assignedAuthor/code','codeSystemVersion'],'В описанном дефекте выбиралась пустая должность из дублирующей записи сотрудника. Исправление заявлено для регионального релиза 35.', ['Сверьте фрагмент assignedAuthor/code и выбранного подписанта.','Передайте поддержке проверку исправления и дублей сотрудников. Не удаляйте записи сотрудников и не назначайте себе другую должность.'],'74317888',date='2023-10-18',version='Расширение 18.10.2023; исправление заявлено для релиза 35',solved=True)
rule('У1-26: даты или серия полиса не соответствуют его виду','У1-26',['effectiveTime','identity:low','identity:high','identity:Series'],'Требуемые даты и наличие серии зависят от вида полиса. В источнике разобраны отдельные варианты полиса старого образца, единого образца и временного свидетельства.', ['Сверьте вид реального полиса и конкретное поле после кода: low — начало, high — окончание, Series — серия.','Попросите регистратора проверить эти реквизиты. Не устанавливайте фиктивный срок и не удаляйте сведения без сверки документа.'],'46008943',date='2023-07-19',solved=True)
rule('У1-27: не передан СНИЛС члена врачебной комиссии','У1-27',['performer','assignedEntity/id','extension'],'В описанном варианте у одного из членов комиссии не заполнен СНИЛС.', ['Сверьте состав комиссии и фрагмент performer в сообщении.','Передайте ответственному за сведения сотрудников проверку реквизита. Не переносите номера сотрудников на личный телефон.'],'46009045',date='2023-10-18')
rule('У1-27: имя члена комиссии выгружено неверно','У1-27',['assignedPerson/name','given'],'В описанном дефекте отчество председателя формировалось как повторный элемент имени. Исправление опубликовано для релиза 33.', ['Убедитесь, что сообщение содержит given и относится к комиссии направления на МСЭ.','Передайте поддержке проверку релиза и исправления. Не удаляйте отчество из сведений сотрудника ради обхода.'],'46009045',date='2023-10-18',version='Исправление в региональном релизе 33',solved=True)
rule('У3-1: выбрана архивная цель направления на МСЭ','У3-1',['SCOPORG','displayName'],'В разобранном случае у архивной цели направления отсутствует требуемое наименование.', ['Сверьте фактическую цель направления и выбранное значение.','Если доступна актуальная запись с тем же смыслом, используйте её по местному порядку. Если нет — обратитесь в поддержку, не меняя цель направления по существу.'],'192217148',date='2026-10-21',solved=True,status_codes=['302'])
rule('У3-2: отсутствует наименование категории гражданства','У3-2',['SCOPORG','displayName'],'Источник описывает незаполненную федеральную формулировку у выбранной категории двойного гражданства.', ['Сверьте, что категория гражданства соответствует действительным данным.','Передайте поддержку справочника. Не меняйте гражданство пациента ради успешной отправки.'],'65110118',date='2026-01-12')
rule('У3-3: выбранное значение в пункте 13 не имеет кода','У3-3',['SCOPORG','act/code'],'В описанном направлении в пункте 13 выбрано значение без федеральных реквизитов, помеченное на удаление.', ['Проверьте выбранное значение в пункте 13 именно вашей формы направления.','Попросите поддержку подобрать актуальную запись с тем же фактическим смыслом. Названия и номера пунктов могут отличаться в другой редакции.'],'166199299',date='2026-01-12')
rule('У3-4: выбранное значение в пункте 10 не имеет кода','У3-4',['SCOPORG','observation/code'],'В описанном направлении у значения пункта 10 отсутствует федеральный код.', ['Сверьте сообщение и пункт 10 соответствующей редакции направления.','Передайте проверку справочника поддержке. Не выбирайте случайное значение только потому, что оно проходит проверку.'],'166199307',date='2026-01-12')
rule('У3-13: указан ЭЛН, но нет сведений о нетрудоспособности','У3-13',['SOCANAM','organizer','component'],'В описанном случае номер листка указан, но связанная таблица частоты и длительности нетрудоспособности не заполнена.', ['Сверьте номер листка и действительные периоды нетрудоспособности.','Заполните относящиеся к нему сведения по исходным документам. Если это уже подписанное направление, сначала согласуйте исправление.'],'46009084',date='2023-12-11',solved=True)
rule('У3-14: не заполнен срок установленной утраты трудоспособности','У3-14',['SOCANAM','value'],'В направлении отмечено повторное освидетельствование по утрате трудоспособности, но не передан срок её установления.', ['Проверьте вид повторного направления и сведения предыдущего решения.','Внесите подтверждённый срок в соответствующее поле; при отсутствии данных уточните их по местному порядку. Не меняйте вид направления ради обхода.'],'46008949',date='2023-06-26',solved=True)
rule('У3-15: причина инвалидности не имеет федеральных реквизитов','У3-15',['SOCANAM','act/code','codeSystemVersion'],'У выбранной причины инвалидности в повторном направлении отсутствуют реквизиты федерального справочника.', ['Сверьте, что причина соответствует предыдущему решению и нужному полю формы.','Передайте поддержке проверку записи справочника. Не заменяйте причину на другую по медицинскому смыслу.'],'166199312',date='2026-01-12')
rule('У3-25: не заполнено поле жалоб','У3-25',['STATECUR','value'],'В описанном направлении пусто поле жалоб гражданина на состояние здоровья.', ['Проверьте соответствующий раздел направления и фактические сведения осмотра.','Заполните поле достоверно; отсутствие жалоб отражайте только если это соответствует осмотру. Исправление подписанной записи согласуйте отдельно.'],'65110183',date='2023-06-26',solved=True)
rule('У3-28 или Core11-1: не передана версия справочника прогноза','У3-28|Core11-1',['SCORES','codeSystemVersion','Клинический прогноз'],'У выбранного клинического прогноза не заполнена версия федерального классификатора.', ['Сверьте выбранный прогноз и наличие codeSystemVersion в сообщении.','Передайте поддержку справочника. Не меняйте клинический прогноз, чтобы обойти технический отказ.'],'87753674',date='2023-12-05')
