rule('Core02-1: адрес не передаёт идентификатор ФИАС','Core02-1',['AOGUID','fias:Address'],'В сообщении отсутствует идентификатор адреса из классификатора, даже если адрес виден текстом.', ['Сверьте, чей адрес указан в сообщении и верен ли он фактически.','Попросите ответственного за регистрацию и поддержку проверить связь адреса с классификатором. Не удаляйте адрес и не редактируйте служебные поля.'],'76972097',date='2024-05-03')
rule('Core03-1: некорректна дата исследования','Core03-1',['Данные анализов','effectiveTime','Диагностические исследования'],'В описанном варианте проверка отвергла дату диагностического исследования или анализа.', ['Сверьте дату в разделе исследований с исходным результатом; уточните поле из полного сообщения.','Исправьте только фактическую ошибку ввода. Если дата верна, передайте поддержку её преобразования в СЭМД.'],'76972104',date='2025-10-27',solved=True)
rule('Core03-1: неверны даты периодов нетрудоспособности','Core03-1',['low','Частота и длительность','organizer'],'В описанном варианте неверно переданы даты в таблице периодов временной нетрудоспособности.', ['Сверьте начало и окончание действительных периодов по исходным документам.','Если данные на форме верны, передайте поддержке код и название таблицы. Не подставляйте технический формат даты вместо обычного поля.'],'76972104',date='2025-10-27',solved=True)
rule('Core03-1: неверно указана дата предыдущего решения или согласия','Core03-1',['Дата согласия','Дата до которой','Направляется повторно'],'Источник описывает разные варианты: дата окончания предыдущего решения, дата согласия либо начало действия полиса. Один Core03-1 не определяет поле.', ['Уточните по полному сообщению и разделу формы, какая дата проверяется.','Сверьте её с фактическими документами; для бессрочного решения уточните предусмотренный системой способ, не придумывая дату окончания.'],'76972104',date='2025-10-27',solved=True)
rule('Core11-1: отмечено наличие ЭЛН, но не указан номер','Core11-1',['INT','Наличие ЭЛН','value'],'В описанном варианте отмечено наличие листка нетрудоспособности, а его номер не передан.', ['Сверьте наличие действительного листка и фрагмент INT в сообщении.','Если листок есть, укажите его действительный номер. Если отметка ошибочна, исправьте её по фактическим сведениям и местному порядку.'],'87753674',date='2023-12-05',solved=True)
rule('В направлении на МСЭ некорректен ОГРН организации местонахождения',None,['ОГРН','identity:Ogrn','Общие ограничения'],'В описанном варианте неверно заполнен ОГРН организации местонахождения пациента.', ['Проверьте, что сообщение относится к организации местонахождения в пункте 13 соответствующей формы.','Попросите ответственного сотрудника сверить её реквизиты. Не используйте ОГРН другой организации и не меняйте местонахождение пациента.'],'87753812',date='2024-01-29')

